"PreToolUse": [
  {
    "matcher": "Bash|PowerShell",
    "hooks": [
      { "type": "command", "command": "node", "args": ["${CLAUDE_PROJECT_DIR}/.claude/hooks/dependency-guard.mjs"], "timeout": 30, "onFailure": "block" }
    ]
  }

// Makes Claude address the reason after a tool call. A failed tool call cannot
// be blocked any more; the reason reaches Claude as context with the error.
export function postToolBlock(reason, event = 'PostToolUse') {
  if (event === 'PostToolUseFailure') postToolContext(reason, event);
  respond({ decision: 'block', reason });
}

// Initial or re-taken snapshot in which nothing violates (a failed
// dependency or reference command is still routed, as when it succeeds).
if (manifests.snapshot && removed.length === 0 && !knownCommand) done();
postToolContext(
  `${what}; the manifest check of ${root} found no violations. If not already done, ${owners}.` +
  (lines.length > 0 ? `\nManifest notes:\n${lines.join('\n')}` : ''),
  event,
);

// Repository-relative path with forward slashes, or null when outside the root.
export function repoRelative(root, filePath) {
  if (!filePath || typeof filePath !== 'string') return null;
  const absolute = canonical(isAbsolute(filePath) ? filePath : resolve(root, filePath));
  const rel = relative(root, absolute);
  if (!rel || rel.startsWith('..') || isAbsolute(rel)) return null;
  return rel.split(sep).join('/');
}

const state = loadManifestState(repo);
const candidates = new Set();
let head = null;
let snapshot = !state.baseline;
if (repo.top) {
  const status = gitOutput(root, ['status', '--porcelain=v2', '-z', '--branch', '--untracked-files=all', '--', ...MANIFEST_PATHSPECS]);
  const fields = (status ?? '').split('\0');
  for (let i = 0; i < fields.length; i += 1) {
    const field = fields[i];
    if (field.startsWith('# branch.oid ')) head = /^[0-9a-f]{40,64}$/.test(field.slice(13)) ? field.slice(13) : null;
    else if (field.startsWith('1 ')) candidates.add(resolve(repo.top, afterFields(field, 8)));
    else if (field.startsWith('2 ')) {
      candidates.add(resolve(repo.top, afterFields(field, 9)));
      i += 1; // the next field is the rename or copy source: a removal for a rename
      if (fields[i]) candidates.add(resolve(repo.top, fields[i]));
    } else if (field.startsWith('u ')) candidates.add(resolve(repo.top, afterFields(field, 10)));
    else if (field.startsWith('? ')) candidates.add(resolve(repo.top, field.slice(2)));
  }
  if (head && state.head && state.head !== head) {
    const moved = gitOutput(root, ['diff', '--name-only', '-z', state.head, head, '--', ...MANIFEST_PATHSPECS]);
    if (moved === null) snapshot = true; // the recorded HEAD cannot be compared
    for (const path of (moved ?? '').split('\0').filter(Boolean)) candidates.add(resolve(repo.top, path));
  }
}
if (!repo.top || snapshot) for (const file of discover(root)) candidates.add(file);

// A script that dispatches on the event name must handle each event it is registered for.
const source = read(`.claude/hooks/${m[1]}`);
if (/\.hook_event_name\b/.test(source) && !new RegExp(`===\\s*'${event}'`).test(source)) {
  fail(`${where}: .claude/hooks/${m[1]} reads hook_event_name but does not handle "${event}"`);
}

for (const [event, tools, script] of REQUIRED_HOOKS) {
  const registered = (Array.isArray(settings?.hooks?.[event]) ? settings.hooks[event] : []).some((group) => {
    const matcher = typeof group?.matcher === 'string' && !['', '*'].includes(group.matcher) ? group.matcher.split('|') : null;
    return tools.every((tool) => !matcher || matcher.includes(tool)) &&
      (group.hooks ?? []).some((hook) => hook?.args?.[0] === `\${CLAUDE_PROJECT_DIR}/.claude/hooks/${script}`);
  });
  if (!registered) {
    fail(`settings.json ${event}: required hook .claude/hooks/${script}${tools.length > 0 ? ` for ${tools.join('|')}` : ''} is not registered`);
  }
}

if (value === '>' || value === '|' || value === '>-' || value === '|-') {
  const block = [];
  while (i + 1 < lines.length && (/^\s+\S/.test(lines[i + 1]) || lines[i + 1].trim() === '')) block.push(lines[(i += 1)].trim());
  data[key] = value.startsWith('>') ? block.join(' ').replace(/\s+/g, ' ').trim() : block.join('\n');
} else if (value === '') {
  const items = [];
  while (i + 1 < lines.length && /^\s*-\s+/.test(lines[i + 1])) items.push(unquote(lines[(i += 1)].replace(/^\s*-\s+/, '').trim()));
  data[key] = items;
} else {
  data[key] = unquote(value);
}

function parseStatus(raw) {
  const fields = raw.split('\0');
  const paths = [];
  for (let i = 0; i < fields.length; i += 1) {
    const entry = fields[i];
    if (entry.length < 4) continue;
    const code = entry.slice(0, 2);
    paths.push(entry.slice(3));
    if (code.includes('R') || code.includes('C')) i += 1; // skip the rename/copy source path
  }
  return paths;
